
const WORDS=[{"id": 0, "w": "厌倦", "p": "yànjuàn", "t": "动词", "m": "chán ngán", "coll": "厌倦生活、感到厌倦", "s": "他渐渐厌倦了一成不变的生活，决定学习一门新技能。"}, {"id": 1, "w": "厌恶", "p": "yànwù", "t": "动词", "m": "chán ghét", "coll": "厌恶欺骗、令人厌恶", "s": "她十分厌恶这种欺骗顾客的行为，当场提出了质疑。"}, {"id": 2, "w": "倘若", "p": "tǎngruò", "t": "连词", "m": "nếu như", "coll": "倘若有机会、倘若如此", "s": "倘若你有机会重新作出选择，你还会坚持原来的决定吗？"}, {"id": 3, "w": "发觉", "p": "fājué", "t": "动词", "m": "phát hiện", "coll": "发觉问题、突然发觉", "s": "走出家门后，他才突然发觉自己忘了带钥匙。"}, {"id": 4, "w": "承诺", "p": "chéngnuò", "t": "动词", "m": "hứa, đồng ý", "coll": "作出承诺、兑现承诺", "s": "既然作出了承诺，就应该尽力把它兑现。"}, {"id": 5, "w": "草率", "p": "cǎoshuài", "t": "形容词", "m": "qua loa, cẩu thả", "coll": "草率决定、处理草率", "s": "面对这么重要的事情，我们不能草率地作出决定。"}, {"id": 6, "w": "对抗", "p": "duìkàng", "t": "动词", "m": "đối chọi, chống lại", "coll": "对抗压力、相互对抗", "s": "双方如果一味对抗，就很难找到解决问题的办法。"}, {"id": 7, "w": "尝试", "p": "chángshì", "t": "动词", "m": "thử", "coll": "大胆尝试、尝试新方法", "s": "遇到困难时，不妨尝试换一种思路。"}, {"id": 8, "w": "盲目", "p": "mángmù", "t": "形容词", "m": "mù quáng", "coll": "盲目跟风、盲目乐观", "s": "选择专业时，不要盲目跟风，而要认真了解自己的兴趣。"}, {"id": 9, "w": "乘", "p": "chéng", "t": "动词", "m": "nhân lúc, tranh thủ (cơ hội)", "coll": "乘机离开、乘人不备", "s": "他乘大家不注意的时候，悄悄把礼物放在了桌上。"}, {"id": 10, "w": "喘气", "p": "chuǎnqì", "t": "动词", "m": "thở; thở hổn hển", "coll": "大口喘气、喘不过气来", "s": "他一口气跑上五楼，站在门口大口喘气。"}, {"id": 11, "w": "饶恕", "p": "ráoshù", "t": "动词", "m": "tha thứ, bỏ qua", "coll": "请求饶恕、得到饶恕", "s": "犯错以后，他真诚地请求对方饶恕自己。"}, {"id": 12, "w": "强迫", "p": "qiǎngpò", "t": "动词", "m": "bắt buộc, ép buộc", "coll": "强迫别人、被迫接受", "s": "父母不应强迫孩子选择他们不喜欢的职业。"}, {"id": 13, "w": "实施", "p": "shíshī", "t": "动词", "m": "thực hiện, thực thi", "coll": "实施计划、实施措施", "s": "经过充分讨论，学校决定下个月实施新的教学计划。"}, {"id": 14, "w": "不料", "p": "bùliào", "t": "连词", "m": "không ngờ, chẳng dè", "coll": "不料发生变化、却不料", "s": "他原本打算早点回家，不料临时接到了加班的通知。"}, {"id": 15, "w": "猛烈", "p": "měngliè", "t": "形容词", "m": "mãnh liệt, mạnh", "coll": "猛烈的风、猛烈地摇晃", "s": "猛烈的风吹得窗户不停地响。"}, {"id": 16, "w": "子弹", "p": "zǐdàn", "t": "名词", "m": "đạn", "coll": "一颗子弹、子弹模型", "s": "博物馆里陈列着一颗子弹的模型，旁边附有详细说明。"}, {"id": 17, "w": "蔑视", "p": "mièshì", "t": "动词", "m": "miệt thị, coi thường", "coll": "蔑视规则、受到蔑视", "s": "任何人都不应该因为别人的出身而蔑视他们。"}, {"id": 18, "w": "眼光", "p": "yǎnguāng", "t": "名词", "m": "ánh mắt; tầm nhìn, khả năng nhìn nhận", "coll": "独特的眼光、长远的眼光", "s": "他凭借独特的眼光，发现了这件作品的价值。"}, {"id": 19, "w": "盯", "p": "dīng", "t": "动词", "m": "nhìn chằm chằm, nhìn chòng chọc", "coll": "盯着屏幕、盯着看", "s": "孩子一直盯着窗外的小鸟，连饭都忘了吃。"}, {"id": 20, "w": "愤怒", "p": "fènnù", "t": "形容词", "m": "phẫn nộ, tức giận", "coll": "感到愤怒、愤怒地说", "s": "得知有人故意破坏公物，大家都感到十分愤怒。"}, {"id": 21, "w": "愚蠢", "p": "yúchǔn", "t": "形容词", "m": "ngu đần, ngu xuẩn", "coll": "愚蠢的决定、显得愚蠢", "s": "为了顾面子而隐瞒错误，是十分愚蠢的做法。"}, {"id": 22, "w": "家伙", "p": "jiāhuo", "t": "名词", "m": "thằng, gã, thằng cha", "coll": "这个家伙、淘气的家伙", "s": "这个家伙虽然平时爱开玩笑，关键时刻却很可靠。"}, {"id": 23, "w": "可恶", "p": "kěwù", "t": "形容词", "m": "đáng ghét", "coll": "可恶的行为、真可恶", "s": "随意丢弃垃圾还拒不改正，这样的行为真可恶。"}, {"id": 24, "w": "耍", "p": "shuǎ", "t": "动词", "m": "giở trò", "coll": "耍花招、耍脾气", "s": "他不愿意靠耍花招赢得比赛，而是坚持公平竞争。"}, {"id": 25, "w": "流氓", "p": "liúmáng", "t": "名词", "m": "lưu manh", "coll": "一群流氓、流氓行为", "s": "面对流氓的威胁，店主及时报警，维护了自己的权益。"}, {"id": 26, "w": "扁", "p": "biǎn", "t": "形容词", "m": "dẹp, bẹp", "coll": "扁的盒子、压扁", "s": "他把空纸盒压扁，整理好后放进了回收箱。"}, {"id": 27, "w": "夕阳", "p": "xīyáng", "t": "名词", "m": "mặt trời chiều", "coll": "夕阳西下、夕阳的余晖", "s": "夕阳西下，河面映着一片金色的光。"}, {"id": 28, "w": "留神", "p": "liúshén", "t": "动词", "m": "chú ý, coi chừng", "coll": "留神脚下、多加留神", "s": "走这段山路时，请留神脚下，不要边走边看手机。"}, {"id": 29, "w": "打猎", "p": "dǎliè", "t": "动词", "m": "đi săn", "coll": "禁止打猎、进山打猎", "s": "为了保护野生动物，当地明确规定禁止在保护区内打猎。"}, {"id": 30, "w": "不顾", "p": "bùgù", "t": "动词", "m": "bất chấp, không đếm xỉa tới", "coll": "不顾危险、不顾反对", "s": "他不顾危险，冲进屋里，把被困的孩子带了出来。"}, {"id": 31, "w": "挣扎", "p": "zhēngzhá", "t": "动词", "m": "vùng vẫy", "coll": "在困境中挣扎、奋力挣扎", "s": "受困的小猫在水里挣扎，路人见状赶紧伸出援手。"}, {"id": 32, "w": "窜", "p": "cuàn", "t": "动词", "m": "tháo chạy", "coll": "窜进树林、到处乱窜", "s": "听见响声，那只兔子一下子窜进了树林。"}, {"id": 33, "w": "摆脱", "p": "bǎituō", "t": "动词", "m": "thoát khỏi", "coll": "摆脱困境、摆脱依赖", "s": "她希望通过自己的努力，逐渐摆脱对父母的依赖。"}, {"id": 34, "w": "死亡", "p": "sǐwáng", "t": "动词", "m": "chết/tử vong", "coll": "因病死亡、死亡人数", "s": "救援人员及时赶到，这次事故中没有人员死亡。"}, {"id": 35, "w": "恰巧", "p": "qiàqiǎo", "t": "副词", "m": "đúng lúc", "coll": "恰巧遇见、恰巧路过", "s": "我去书店的时候，恰巧遇见了多年没见的老师。"}, {"id": 36, "w": "毫无", "p": "háowú", "t": "短语", "m": "không một chút", "coll": "毫无准备、毫无意义", "s": "讨论之前如果毫无准备，就很难提出有价值的意见。"}, {"id": 37, "w": "抵抗", "p": "dǐkàng", "t": "动词", "m": "chống cự", "coll": "抵抗诱惑、抵抗外力", "s": "面对不合理的要求，他们选择团结起来，共同抵抗。"}, {"id": 38, "w": "部位", "p": "bùwèi", "t": "名词", "m": "bộ phận (cơ thể)", "coll": "受伤部位、身体部位", "s": "医生仔细检查了他受伤的部位，建议他暂时休息。"}, {"id": 39, "w": "悲惨", "p": "bēicǎn", "t": "形容词", "m": "bi thảm, thảm thương", "coll": "悲惨的经历、命运悲惨", "s": "这部小说讲述了一个家庭在战争年代的悲惨经历。"}, {"id": 40, "w": "未免", "p": "wèimiǎn", "t": "副词", "m": "có hơi, có phần", "coll": "未免太早、未免草率", "s": "仅凭一次考试就否定他的努力，未免太草率了。"}, {"id": 41, "w": "残忍", "p": "cánrěn", "t": "形容词", "m": "tàn nhẫn", "coll": "残忍的行为、手段残忍", "s": "我们应该制止这种残忍地伤害动物的行为，保护生命。"}, {"id": 42, "w": "良心", "p": "liángxīn", "t": "名词", "m": "lương tâm", "coll": "凭良心做事、问心无愧", "s": "无论做什么工作，都应该凭良心做事，对得起自己的责任。"}, {"id": 43, "w": "锋利", "p": "fēnglì", "t": "形容词", "m": "sắc bén", "coll": "锋利的刀、十分锋利", "s": "这把刀十分锋利，使用的时候一定要小心。"}, {"id": 44, "w": "缠绕", "p": "chánrào", "t": "动词", "m": "quấn quanh", "coll": "缠绕树干、互相缠绕", "s": "几根藤条缠绕着树干，一直伸向高处。"}, {"id": 45, "w": "耗费", "p": "hàofèi", "t": "动词", "m": "hao tốn", "coll": "耗费时间、耗费精力", "s": "这项研究耗费了团队成员大量的时间和精力。"}, {"id": 46, "w": "缺口", "p": "quēkǒu", "t": "名词", "m": "lỗ hổng, chỗ hở", "coll": "资金缺口、填补缺口", "s": "通过多方努力，公司终于填补了项目的资金缺口。"}, {"id": 47, "w": "举世瞩目", "p": "jǔshì zhǔmù", "t": "成语", "m": "thu hút sự chú ý của cả thế giới", "coll": "举世瞩目的成就、举世瞩目的盛会", "s": "这场举世瞩目的体育盛会吸引了来自各地的运动员和观众。"}];
